 $('repeat-status').onclick=()=>task(async()=>{const c=requireRepeater(),key=hex(c.publicKey),conn=getConnection();logger('Requesting status…');const x=await exclusive(()=>conn.getStatus(c.publicKey,10000));if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key)return;const view=$('repeat-status-view');view.hidden=false;renderStatus(view,x);logger('Status received.');view.scrollIntoView({behavior:'smooth',block:'nearest'});});
 $('repeat-telemetry').onclick=()=>task(async()=>{const c=requireRepeater(),key=hex(c.publicKey),conn=getConnection();logger('Requesting telemetry…');const x=await exclusive(()=>conn.getTelemetry(c.publicKey,10000));if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key)return;const view=$('repeat-status-view');view.hidden=false;renderTelemetry(view,decodeTelemetry(x.lppSensorData));logger('Telemetry received.');view.scrollIntoView({behavior:'smooth',block:'nearest'});});
 async function refreshNeighbours(){const c=requireRepeater(),key=hex(c.publicKey),conn=getConnection();logger('Requesting neighbours…');const entries=[];let total=0;do{if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key)throw Error('Repeater or connection changed during refresh.');const page=await exclusive(()=>conn.getNeighbours(c.publicKey,10,entries.length,0,8));total=page.totalNeighboursCount;entries.push(...page.neighbours);if(!page.neighbours.length)break;}while(entries.length<total&&entries.length<500);if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key)throw Error('Repeater or connection changed during refresh.');drawNeighbours(picked(),entries,total);logger(`Received ${entries.length} of ${total} neighbours.`);return entries.length;}
 $('repeat-neighbours').onclick=()=>task(refreshNeighbours);
 $('repeat-reset-path').onclick=()=>task(async()=>{let c=requireRepeater();await exclusive(()=>getConnection().resetPath(c.publicKey));logger('Saved direct path cleared; next request will use flooding.');});
 async function sendCommand(command,settingRead=false,confirmed=false){if(readingSettings&&!settingRead)throw Error('Wait for the settings read to finish.');const c=requireRepeater();if(loggedKey!==hex(c.publicKey)||loggedConnection!==getConnection())throw Error('Log in to this repeater first');command=command.trim();if(!command)throw Error('Enter a command');if(new TextEncoder().encode(command).length>120)throw Error('Command too long');if(!confirmed&&/^(reboot|shutdown|poweroff|erase|factory|password|set |clock sync|region (?:deny|remove|delete))/i.test(command)&&!confirm(`Send this change to ${c.advName||'the repeater'}?\n\n${command}`))return;await exclusive(async()=>{const wait=Math.max(0,(lastCliSecond+1)*1000-Date.now());if(wait)await new Promise(resolve=>setTimeout(resolve,wait));if(!state.connected||hex(picked()?.publicKey)!==hex(c.publicKey))throw Error('Repeater or connection changed.');lastCliSecond=Math.floor(Date.now()/1000);return getConnection().sendTextMessage(c.publicKey,command,Constants.TxtTypes.CliData)});logger('> '+command+'\nQueued; response will appear when received.');}
 $('repeat-send').onclick=()=>task(()=>sendCommand($('repeat-command').value));$('repeat-quick-send').onclick=()=>task(()=>sendCommand($('repeat-quick').value));
 for(const [id,command] of [['repeat-clock','clock'],['repeat-clock-sync','clock sync'],['repeat-advert-local','advert.zerohop'],['repeat-advert-flood','advert']])$(id).onclick=()=>task(()=>sendCommand(command));
 function cancelDiscovery(message){discoveryRun++;if(discoveryTimer!==null){clearInterval(discoveryTimer);discoveryTimer=null}$('repeat-discover').disabled=false;$('discovery-countdown').textContent='';$('discovery-status').textContent=message;}
 $('repeat-discover').onclick=()=>task(async()=>{const c=requireRepeater(),key=hex(c.publicKey),conn=getConnection(),run=++discoveryRun,button=$('repeat-discover');button.disabled=true;$('discovery-box').hidden=false;$('discovery-countdown').textContent='';$('discovery-status').textContent='Sending discovery command…';try{await sendCommand('discover.neighbors');if(run!==discoveryRun)return;if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key){cancelDiscovery('Discovery cancelled: repeater or connection changed.');return}const deadline=Date.now()+60000;$('discovery-countdown').textContent='60 seconds';$('discovery-status').textContent='Discovery command queued. Waiting before refreshing neighbours…';discoveryTimer=setInterval(async()=>{if(run!==discoveryRun)return;if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key){cancelDiscovery('Discovery cancelled: repeater or connection changed.');return}const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('discovery-countdown').textContent=remaining+(remaining===1?' second':' seconds');if(remaining>0)return;clearInterval(discoveryTimer);discoveryTimer=null;$('discovery-status').textContent='Refreshing neighbours…';try{const count=await refreshNeighbours();if(run===discoveryRun)$('discovery-status').textContent=`Refresh complete: ${count} ${count===1?"neighbour":"neighbours"} received.`;}catch(e){if(run===discoveryRun){$('discovery-status').textContent='Refresh failed: '+(e?.message||String(e));logger('Error: '+(e?.message||String(e)));toast('Neighbour refresh failed','error')}}finally{if(run===discoveryRun)button.disabled=false}},1000);}catch(e){if(run===discoveryRun){button.disabled=false;$('discovery-status').textContent='Discovery failed: '+(e?.message||String(e));}throw e}});
 async function readSetting(command){const c=requireRepeater(),key=hex(c.publicKey);if(state.contacts.filter(x=>hex(x.publicKey,6)===hex(c.publicKey,6)).length!==1)throw Error('Repeater key prefix is ambiguous; replies cannot be matched safely.');const alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz',number=nextTag++%(alphabet.length*alphabet.length),tag=alphabet[Math.floor(number/alphabet.length)]+alphabet[number%alphabet.length]+'|';let timer,resolve,reject;const result=new Promise((yes,no)=>{resolve=yes;reject=no});result.catch(()=>{});pendingSetting={key,tag,resolve,reject};timer=setTimeout(()=>{if(pendingSetting?.resolve===resolve){pendingSetting=null;reject(Error('No matching response to '+command+'. The repeater may be unreachable or may not support tagged CLI replies.'))}},15000);try{await sendCommand(tag+command,true);return await result}finally{clearTimeout(timer);if(pendingSetting?.resolve===resolve)pendingSetting=null}}
 async function repeaterPathHash(save){if(readingSettings)throw Error('Wait for the settings read to finish.');const c=requireRepeater(),key=hex(c.publicKey),select=$('repeat-path-hash'),status=$('repeat-path-hash-status'),choice=select.value;if(loggedKey!==key)throw Error('Log in to this repeater first.');if(save&&(choice===''||!['0','1','2'].includes(choice)))throw Error('Choose an advert path size.');readingSettings=true;$('repeat-read-path-hash').disabled=true;$('repeat-set-path-hash').disabled=true;try{status.textContent=save?'Saving and checking…':'Reading current setting…';if(save){const reply=(await readSetting('set path.hash.mode '+choice)).trim();if(!/^OK\b/i.test(reply))throw Error('Repeater did not confirm the change: '+reply)}const reply=(await readSetting('get path.hash.mode')).trim(),match=reply.match(/^>\s*([012])\s*$/);if(!match)throw Error('Unexpected path size response: '+reply);if(hex(picked()?.publicKey)!==key)return;select.value=match[1];status.textContent=`Current repeater advert setting: ${Number(match[1])+1} byte(s) per hop.`;if(save&&match[1]!==choice)throw Error('Repeater reported a different value after saving.');}catch(e){status.textContent=e?.message||'Could not read path size.';throw e}finally{readingSettings=false;$('repeat-read-path-hash').disabled=false;$('repeat-set-path-hash').disabled=false}}
 async function regionOperation(command,mutate=false){if(readingSettings)throw Error('Wait for the current settings read.');const c=requireRepeater(),key=hex(c.publicKey);if(loggedKey!==key)throw Error('Log in first.');if(mutate&&!confirm(`Send this region command to ${c.advName||'the repeater'}?\n\n${command}`))return;readingSettings=true;const status=$('repeat-region-status');try{status.textContent='Waiting for matched response…';const reply=await readSetting(command);if(/^\s*(err|error)/i.test(reply))throw Error(reply);if(hex(picked()?.publicKey)!==key)throw Error('Repeater changed.');if(command==='region'){$('repeat-region-tree').textContent=reply;status.textContent='Region tree received. Review wildcard and flood permissions.';}else status.textContent=`${command}: ${reply}. Read the tree to review; use Save region changes to persist.`;}catch(e){status.textContent=e.message;throw e}finally{readingSettings=false}}
 const regionName=id=>{const value=$(id).value.trim();if(!/^(?:\*|[A-Za-z0-9_-]{1,30})$/.test(value))throw Error('Enter a valid region code or *.');return value};
 $('repeat-region-read').onclick=()=>task(()=>regionOperation('region'));
