 $('repeat-read-path-hash').onclick=()=>task(()=>repeaterPathHash(false));$('repeat-set-path-hash').onclick=()=>task(()=>repeaterPathHash(true));
 $('repeat-read-settings').onclick=()=>task(async()=>{if(readingSettings)throw Error('A settings read is already running.');readingSettings=true;const button=$('repeat-read-settings'),status=$('repeat-settings-status');button.disabled=true;try{for(const [cmd,id] of [['get name','repeat-setting-name'],['get repeat','repeat-setting-forward'],['get lat','repeat-setting-lat'],['get lon','repeat-setting-lon'],['get role','repeat-read-role'],['get advert.interval','repeat-read-advert'],['get flood.max','repeat-read-flood']]){status.textContent='Reading '+cmd.substring(4)+'…';const reply=await readSetting(cmd);if(!reply.startsWith('>')){if(id.startsWith('repeat-read-')){$(id).textContent='Unavailable: '+reply;continue}throw Error('Unexpected response to '+cmd+': '+reply)}const value=reply.slice(1).trim();if(id==='repeat-setting-forward'&&!['on','off'].includes(value))throw Error('Unexpected forwarding response: '+value);if((id==='repeat-setting-lat'||id==='repeat-setting-lon')&&(!value||!Number.isFinite(Number(value))))throw Error('Invalid location response: '+value);if(id.startsWith('repeat-read-'))$(id).textContent=value;else $(id).value=value;}repeaterLocationMap.sync();status.textContent='Settings received from matching repeater replies. Check values before saving.';}catch(e){status.textContent=e.message;throw e}finally{readingSettings=false;button.disabled=false}});
 $('repeat-set-name').onclick=()=>task(async()=>{const value=$('repeat-setting-name').value.trim();if(!value||/[\r\n]/.test(value))throw Error('Enter a valid name.');await sendCommand('set name '+value)});
 $('repeat-set-forward').onclick=()=>task(()=>sendCommand('set repeat '+$('repeat-setting-forward').value));
 $('repeat-set-location').onclick=()=>task(async()=>{const lat=$('repeat-setting-lat').value,lon=$('repeat-setting-lon').value,status=$('repeat-location-status'),c=requireRepeater(),key=hex(c.publicKey),conn=getConnection();if(loggedKey!==key||loggedConnection!==conn)throw Error('Log in to this repeater first');if(lat===''||lon===''||!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))||Math.abs(Number(lat))>90||Math.abs(Number(lon))>180)throw Error('Enter valid latitude and longitude.');if(!confirm(`Set the location of ${c.advName||'this repeater'} to ${Number(lat)}, ${Number(lon)}?`)){status.textContent='Location change cancelled.';return}status.textContent='Sending location to repeater…';try{await sendCommand('set lat '+Number(lat),false,true);if(!state.connected||getConnection()!==conn||hex(picked()?.publicKey)!==key||loggedKey!==key)throw Error('Connection or repeater changed after latitude was queued; longitude was not sent.');await sendCommand('set lon '+Number(lon),false,true);status.textContent='Location commands queued; not yet confirmed. Use Read settings to check both coordinates.'}catch(e){status.textContent='Location may be partially changed. Read settings before retrying. '+(e?.message||'');throw e}});
 function location(c){let a=Number(c?.advLat),b=Number(c?.advLon);if(!Number.isFinite(a)||!Number.isFinite(b))return null;if(Math.abs(a)>90||Math.abs(b)>180){a/=1e6;b/=1e6}return (!a&&!b)||Math.abs(a)>90||Math.abs(b)>180?null:[a,b]}
 function tooltipText(value){const el=document.createElement('span');el.textContent=value;return el}
 function drawNeighbours(c,entries,total){if(!neighbourMap)return;if(neighbourLayer)neighbourLayer.clearLayers();else neighbourLayer=L.layerGroup().addTo(neighbourMap);const origin=location(c),points=[],list=$('neighbour-list');list.replaceChildren();let drawn=0,unmapped=0;const nodes=[];for(const n of entries){const prefix=hex(n.publicKeyPrefix),matches=state.contacts.filter(x=>hex(x.publicKey).startsWith(prefix)),other=matches.length===1?matches[0]:null,pos=location(other),name=other?.advName||prefix;const reason=matches.length>1?'ambiguous key':!other?'not in contacts':!pos?'no advertised location':!origin?'selected repeater has no location':'';const row=document.createElement('div');row.textContent=`${name} · SNR ${n.snr} dB · heard ${n.heardSecondsAgo} s ago${reason?' · '+reason:''}`;list.append(row);if(pos){nodes.push({pos,name});points.push(pos)}if(origin&&pos){L.polyline([origin,pos],{color:'#087ac1',weight:5,opacity:.95}).addTo(neighbourLayer).bindTooltip(`SNR ${n.snr} dB`,{permanent:true});drawn++}else unmapped++}if(origin){points.push(origin);nodes.push({pos:origin,name:c.advName||'Selected repeater',origin:true})}for(const node of nodes)L.circleMarker(node.pos,{radius:node.origin?10:8,color:'#142633',weight:3,fillColor:node.origin?'#ffb52e':'#16b967',fillOpacity:1}).addTo(neighbourLayer).bindTooltip(tooltipText(node.name),{permanent:true,direction:'top',className:'neighbour-name'});if(points.length>1)neighbourMap.fitBounds(points,{padding:[35,35]});else if(points.length)neighbourMap.setView(points[0],10);$('neighbour-map-status').textContent=`${drawn} links mapped; ${unmapped} cannot be linked without an unambiguous contact and both locations. ${entries.length} of ${total} neighbours received.`;}

 function handleMessage(msg){if(msg.txtType!==Constants.TxtTypes.CliData)return false;const current=picked(),prefix=hex(msg.pubKeyPrefix,6);if(current&&hex(current.publicKey,6)===prefix)logger('< '+msg.text);if(pendingSetting&&pendingSetting.key.startsWith(prefix)&&prefix.length===12&&msg.text.startsWith(pendingSetting.tag)){const waiting=pendingSetting;pendingSetting=null;waiting.resolve(msg.text.slice(waiting.tag.length))}return true;}
 async function monitoringClock(contact,doSync=false){
  const key=hex(contact?.publicKey),conn=getConnection();if(!state.connected||!conn||contact?.type!==2)throw Error('Connect the radio and select a known repeater.');
  if(readingSettings||pendingSetting)throw Error('Another repeater command is waiting for a reply. Try again shortly.');
  if(state.contacts.filter(x=>hex(x.publicKey,6)===hex(contact.publicKey,6)).length!==1)throw Error('Repeater key prefix is ambiguous; cannot safely match replies.');
  readingSettings=true;
  try{
   if(loggedKey!==key||loggedConnection!==conn){const saved=await credential('get',key);if(!saved.password)throw Error('Log in on the Repeaters page with this repeater selected, or save its admin password there first.');await exclusive(()=>conn.login(contact.publicKey,saved.password,10000));}
   if(!state.connected||getConnection()!==conn)throw Error('Radio disconnected.');
   async function request(command){
    const alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz',number=nextTag++%(alphabet.length*alphabet.length),tag=alphabet[Math.floor(number/alphabet.length)]+alphabet[number%alphabet.length]+'|';let timer,resolve,reject;
    const result=new Promise((yes,no)=>{resolve=yes;reject=no});result.catch(()=>{});pendingSetting={key,tag,resolve,reject};
    timer=setTimeout(()=>{if(pendingSetting?.resolve===resolve){pendingSetting=null;reject(Error('No matching clock response. Check the link, login and repeater firmware.'))}},15000);
    try{await exclusive(async()=>{const wait=Math.max(0,(lastCliSecond+1)*1000-Date.now());if(wait)await new Promise(done=>setTimeout(done,wait));if(!state.connected||getConnection()!==conn)throw Error('Radio disconnected.');lastCliSecond=Math.floor(Date.now()/1000);const text=typeof command==='function'?command():command;return conn.sendTextMessage(contact.publicKey,tag+text,Constants.TxtTypes.CliData)});return await result;}
    finally{clearTimeout(timer);if(pendingSetting?.resolve===resolve)pendingSetting=null;}
   }
   if(doSync){const reply=await request(()=>`time ${Math.floor(Date.now()/1000)}`);if(!/^OK\s*-\s*clock set:/i.test(reply.trim()))throw Error('Repeater did not accept the PC time: '+reply.trim());}
   const reply=(await request('clock')).trim();if(!/^\d{1,2}:\d{2}\s*-\s*\d{1,2}\/\d{1,2}\/\d{4}\s+UTC$/i.test(reply))throw Error('Unexpected clock response: '+reply);
   return reply;
  }finally{readingSettings=false;}
 }

 function coordinate(which){const a=$(`terrain-${which}-lat`).value,b=$(`terrain-${which}-lon`).value;if(a===''||b==='')throw Error('Enter latitude and longitude for point '+which.toUpperCase());const lat=Number(a),lon=Number(b);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw Error('Invalid coordinates');return [lat,lon];}
 function number(id,min,max){const x=Number($(id).value);if($(id).value===''||!Number.isFinite(x)||x<min||x>max)throw Error('Check '+$(id).closest('label').innerText);return x;}
 function setPoint(which,p){invalidateTerrain();$(`terrain-${which}-lat`).value=p[0].toFixed(6);$(`terrain-${which}-lon`).value=p[1].toFixed(6);mark(which,p);}
